// One shared patience clock per unhappy party. UI and departure use this clock.
export const NEEDS={atmosphere:['🎵','Too quiet for our group'],outlets:['🔌','Needs power'],noise:['🔇','Needs quiet'],lighting:['💡','Needs light'],comfort:['🪑','Needs comfort'],crowding:['↔','Needs space'],groupSeating:['👥','Seats together'],noSeat:['🪑','Needs a seat'],accessibility:['♿','Wider route'],waiting:['☕','Waiting for service'],blockedRoute:['🚧','Blocked route'],bathroom:['🚻','Needs a bathroom'],bathroomAccess:['🚻','Bathroom blocked'],bathroomQueue:['🚻','Bathroom queue']};
export function beginConcern(sim,g,key){if(!g.concern)g.concern={key,total:sim.cafe.dayNumber>=3?24:30,remaining:sim.cafe.dayNumber>=3?24:30,started:sim.time};else g.concern.key=key;return g.concern}
export function resolveConcern(sim,g){if(g.concern){g.rescued=true;g.reliefUntil=sim.time+4;g.sat=Math.min(1,g.sat+.12);g.satIntegral=g.sat*Math.max(0,g.seatTime||0);g.concern=null;sim.say(g,'Thank you — much better!')}}
export function rewardGuest(sim,g){if(g.rewarded||!g.served||g.concern)return;g.rewarded=true;const previousStreak=sim.streak;sim.streak+=g.size;sim.bestStreak=Math.max(sim.bestStreak,sim.streak);sim.reputation=Math.min(100,sim.reputation+2);const multiplier=Math.min(3,1+Math.floor(sim.streak/3)*.5),tip=Math.round(2*g.size*multiplier);sim.tips+=tip;sim.revenue+=tip;sim.transactions.push({id:sim.transactions.length+1,guest:g.id,time:sim.time,amount:tip,cost:0,tip:true,multiplier});g.purchaseTime=sim.time;g.lastSpend=tip;sim.rewardMessage=`${sim.streak} happy in a row · ${multiplier}× tips`;for(let milestone=(Math.floor(previousStreak/3)+1)*3;milestone<=sim.streak;milestone+=3){if(!sim.rewardedMilestones.has(milestone)){sim.rewardedMilestones.add(milestone);sim.upgradeRewards+=30;sim.rewardMessage+=' · $30 upgrade credit'}}sim.rewardAt=sim.time;}
export function loseGuest(sim,g){if(g.lossCounted)return;g.lossCounted=true;const lostStreak=sim.streak;sim.streak=0;if(lostStreak>0){sim.streakBreak={id:(sim.streakBreak?.id||0)+1,count:lostStreak,time:sim.time};}sim.reputation=Math.max(0,sim.reputation-4);sim.unhappyDepartures+=g.size;sim.lostOpportunity+=g.served?4*g.size:10*g.size;sim.rewardMessage='Guest left unhappy · streak reset';sim.rewardAt=sim.time;}
